#include "postquantiquecoin/wallet/WalletManager.h"
#include <filesystem>
namespace pqc { WalletManager::WalletManager(std::filesystem::path d,PQCryptoProvider* c):dir_(std::move(d)),crypto_(c){ std::filesystem::create_directories(dir_); } std::filesystem::path WalletManager::PathFor(const std::string& n) const { return dir_/(n+".wallet"); } Result<void> WalletManager::CreateWallet(const std::string& n,const std::string& p){ if(std::filesystem::exists(PathFor(n))) return Result<void>::Err("wallet exists"); auto w=Wallet::CreateNew(n,p,PathFor(n),crypto_); if(w.IsErr()) return Result<void>::Err(w.Error()); open_[n]=std::make_unique<Wallet>(std::move(w.Value())); return Result<void>::Ok(); } Result<void> WalletManager::OpenWallet(const std::string& n){ auto w=std::make_unique<Wallet>(n,PathFor(n),crypto_); auto r=w->Load(); if(r.IsErr()) return r; open_[n]=std::move(w); return Result<void>::Ok(); } void WalletManager::CloseWallet(const std::string& n){ open_.erase(n); } Wallet* WalletManager::GetWallet(const std::string& n){ auto it=open_.find(n); return it==open_.end()?nullptr:it->second.get(); } std::vector<std::string> WalletManager::ListWallets() const { std::vector<std::string> v; if(!std::filesystem::exists(dir_)) return v; for(auto& e:std::filesystem::directory_iterator(dir_)) if(e.path().extension()==".wallet") v.push_back(e.path().stem().string()); return v; } Result<void> WalletManager::DeleteWallet(const std::string& n,bool allow){ if(!allow) return Result<void>::Err("dangerous delete flag required"); open_.erase(n); std::filesystem::remove(PathFor(n)); return Result<void>::Ok(); } }
